// Fake pi-ai classifiers for bridge tests. No network or credentials. They
// only see failed messages, as the real ones only classify stopReason "error".
export function isRetryableAssistantError(message) {
  if (message.stopReason !== "error" || !message.errorMessage) return false;
  if (/insufficient_quota/i.test(message.errorMessage)) return false;
  return /\b(?:429|503)\b|overloaded/i.test(message.errorMessage);
}

export function isContextOverflow(message) {
  return message.stopReason === "error" && /prompt is too long/i.test(message.errorMessage ?? "");
}
